\label{remark:assumptions}

Let $\ell_n=\mathbb{E}[N_{n,1}]$ and assume that there
is a fixed constant $\alpha\in(0,\infty)$ such that
\begin{align}
\ell_n&=\mathbb{E}[N_{n,1}],
&
\frac{\log n}{\ell_n}
&\longrightarrow\alpha\in(0,\infty),
&
\mathbb{E}[N_{n,1}^2]&=\Theta((\log n)^2)
\qquad \text{when}\ n\to\infty.
\label{eq:renewal-assumptions}
\end{align}

\label{thm:renewal-capacity}
Consider the noisy TPC with substitution probability
$p\in(0,1/2)$, and let $\kappa=1-h_2(p)$, where $h_2(p)=-p\log p-(1-p)\log(1-p)$ is the binary entropy
function.
Under Assumption~\ref{remark:assumptions}, we have that
\begin{equation}
 \limsup_{n\to\infty}\frac1n
 \sup_{P_{\mathbf{X}}}I(\mathbf{X};\mathcal{Y})
 \le\limsup_{n\to\infty}r_n(\kappa).
 \label{eq:renewal-converse}
\end{equation}

\label{cor:geometric}
Consider the independent-cut torn paper channel with substitution errors, with
break probability~$q_n$ satisfying
$q_n\log n\to\alpha\in(0,\infty)$ and substitution probability
$p\in(0,1/2)$. Let $C(\alpha,p)$ denote its capacity.
Theorem~\ref{thm:renewal-capacity}, together with the achievable
rate in~\cite[Theorem~3]{ravi2024recovering}, implies that
\begin{equation}
 C(\alpha,p)=\kappa e^{-\alpha/\kappa}.
 \label{eq:geometric-capacity}
\end{equation}

\label{thm:nsc}
Consider the NSC with substitution probability $p\in(0,1/2)$. Under Assumption~\ref{remark:assumptions}, we have
\begin{equation}
 \limsup_{n\to\infty}\frac{1}{n}\sup_{P_{\mathbf{X}}}I(\mathbf{X};\mathcal{Y})\leq(1-h_2(p)-\alpha)^+.
 \label{eq:nsc-converse}
\end{equation}
Together with the achievable rate of~\cite{shomorony2019capacity},
it follows that the capacity of the NSC is $(1-h_2(p)-\alpha)^+$.

\label{prop:uniform}
Fix $\epsilon>0$ and $\delta\in(0,1)$, and define
\begin{equation*}
 b=\frac{1-\delta}{\kappa+\epsilon},
 \qquad\lambda=\kappa b\in(0,1).
\end{equation*}
There is a constant $c_2=c_2(p,\epsilon,\delta)$ such that
for every $m,L\ge1$,
\begin{equation}
 \mathsf{C}_p(m,L)
 \le m(\kappa L-\lambda\log m)^+
       +c_2m+2b\,m^{1-\delta}\log(m+1).
 \label{eq:uniform-shuffling}
\end{equation}

Suppose the decoder knows
the exact cut locations $\mathbf{T}$ from
Lemma~\ref{lem:sets}, in addition to $\mathcal{Y}$.
Then
\begin{align}
I(\mathbf{X};\mathcal{Y})
&\leq I(\mathbf{X};\mathcal{Y},\mathbf{T})
=I(\mathbf{X};\mathbf{T})+I(\mathbf{X};\mathcal{Y}\mid\mathbf{T})
\overset{(\dagger)}{=}
I(\mathbf{X};\mathcal{Y}\mid\mathbf{T}),
\label{eq:reveal-cuts}
\end{align}
where $(\dagger)$ follows from the
independence of $\mathbf{X}$ and $\mathbf{T}$.

Fix $\epsilon>0$ and $\delta\in(0,1)$, and use the
constants $b,\lambda,c_2$ from
Proposition~\ref{prop:uniform}.
We first consider fixed cut locations
$\mathbf{T}=\mathbf{t}$ with $K_n\leq c_1n/\log n$
(in calculations conditional on $\mathbf{T}=\mathbf{t}$,
$K_n$ and $L_{n,j}$ refer to  fixed values
determined by $\mathbf{t}$), for which we have,
\begin{align}
I(\mathbf{X};\mathcal{Y}\mid\mathbf{T}=\mathbf{t})
&\overset{\eqref{eq:set-information}}{\leq}
\sum_{L\in\mathcal{L}}\mathsf{C}_p(m_L,L)
\notag\\
&\overset{\eqref{eq:uniform-shuffling}}{\leq}
\sum_{L\in\mathcal{L}}m_L(\kappa L-\lambda\log m_L)^+
+c_2K_n
+2b\sum_{L\in\mathcal{L}}m_L^{1-\delta}\log(m_L+1)
\notag\\
&\overset{\eqref{eq:counts-power}}{\leq}
\sum_{L\in\mathcal{L}}m_L(\kappa L-\lambda\log m_L)^+
+c_2K_n
+2b\log(n+1)(2n)^{\delta/2}K_n^{1-\delta}
\notag\\
&\overset{(\dagger)}{\leq}
\sum_{j=1}^{K_n}(\kappa L_{n,j}-\lambda\log n)^+
+\lambda\sum_{L\in\mathcal{L}}m_L\log\frac{n}{m_L}
+c_2K_n
+2b\log(n+1)(2n)^{\delta/2}K_n^{1-\delta}
\notag\\
&\overset{\eqref{eq:counts-entropy}}{\leq}
\sum_{j=1}^{K_n}(\kappa L_{n,j}-\lambda\log n)^+
+(c_2+\lambda\log e)K_n
+2\lambda K_n\log\frac{n}{K_n}
+2b\log(n+1)(2n)^{\delta/2}K_n^{1-\delta},
\label{eq:replace-length-logarithms}
\end{align}
where $(\dagger)$ follows since
$\kappa L-\lambda\log m_L
=\kappa L-\lambda\log n+\lambda\log(n/m_L)$
and $(a+d)^+\leq a^++d$ for $d\geq0$.

We next bound the last three terms in~\eqref{eq:replace-length-logarithms},
divided by~$n$, one at a time.
Since $K_n/n\leq c_1/\log n<1/e$ for a sufficiently large~$n$,
we have,
\begin{align*}
\frac{(c_2+\lambda\log e)K_n}{n}
\leq\frac{c_1(c_2+\lambda\log e)}{\log n}.
\end{align*}
For the second term, we cannot bound
$\log(n/K_n)$ by itself; instead we bound the product
$K_n\log(n/K_n)$.
The function $x\mapsto x\log(n/x)$ is nondecreasing on $(0,n/e]$.
Thus, we have
\begin{align*}
\frac{2\lambda K_n\log(n/K_n)}{n}
\leq\frac{2\lambda}{n}\cdot\frac{c_1n}{\log n}
\log\left(\frac{n}{c_1n/\log n}\right)
=\frac{2\lambda c_1\log(\log n/c_1)}{\log n}.
\end{align*}
For the third term, we use $K_n^{1-\delta}\leq(c_1n/\log n)^{1-\delta}$,
which holds since $1-\delta>0$:
\begin{align*}
\frac{2b\log(n+1)(2n)^{\delta/2}K_n^{1-\delta}}{n}
\leq\frac{2b\log(n+1)\,2^{\delta/2}n^{\delta/2}\,c_1^{1-\delta}n^{1-\delta}}
{n(\log n)^{1-\delta}}
=\frac{2^{1+\delta/2}bc_1^{1-\delta}\log(n+1)}
{n^{\delta/2}(\log n)^{1-\delta}}.
\end{align*}
Adding the three bounds shows that the last three terms
in~\eqref{eq:replace-length-logarithms}, divided by~$n$, are at most
\begin{align}
\frac{c_1(c_2+\lambda\log e)}{\log n}
+\frac{2\lambda c_1\log(\log n/c_1)}{\log n}
+\frac{2^{1+\delta/2}bc_1^{1-\delta}\log(n+1)}
{n^{\delta/2}(\log n)^{1-\delta}}
=:e_n.
\notag
\end{align}
Each of the three terms defining $e_n$ tends to
zero as $n\to\infty$, so $e_n\to0$ as $n\to\infty$.


Since~$\lambda\in(0,1)$ (see Proposition~\ref{prop:uniform}), it follows that
\begin{align}
I(\mathbf{X};\mathcal{Y}\mid\mathbf{T}=\mathbf{t})
&\overset{\eqref{eq:replace-length-logarithms}}{\leq}
\sum_{j=1}^{K_n}(\kappa L_{n,j}-\lambda\log n)^+
+ne_n
\notag\\
&\overset{(\dagger)}{\leq}
\sum_{j=1}^{K_n}(\kappa L_{n,j}-\log n)^+
+(1-\lambda)K_n\log n+ne_n
\notag\\
&\leq
\sum_{j=1}^{K_n}(\kappa L_{n,j}-\log n)^+
+(1-\lambda)c_1n+ne_n,
\label{eq:partition-small-fragment-number}
\end{align}
where $(\dagger)$ follows since
$\kappa L_{n,j}-\lambda\log n
=\kappa L_{n,j}-\log n+(1-\lambda)\log n$ and since~$(a+d)^+\le a^++d$ for every real~$a$ and every~$d\geq0$; applying this with~$d=(1-\lambda)\log n$ to each of the~$K_n$ terms and summing over~$j$ produces the term~$(1-\lambda)K_n\log n$.




We now average over all cut locations to get the final bound for
$I(\mathbf{X};\mathcal{Y})$.
\begin{align}
\frac1n I(\mathbf{X};\mathcal{Y})
&\overset{\eqref{eq:reveal-cuts}}{\leq}
\frac1n I(\mathbf{X};\mathcal{Y}\mid\mathbf{T})\overset{(\dagger)}{=}
\frac1n\sum_{\mathbf{t}}
\Pr(\mathbf{T}=\mathbf{t})
I(\mathbf{X};\mathcal{Y}\mid\mathbf{T}=\mathbf{t})
\notag\\
&\overset{(\dagger\dagger)}{=}
\frac1n\sum_{\mathbf{t}}
\Pr(\mathbf{T}=\mathbf{t},\,K_n\leq c_1n/\log n)
I(\mathbf{X};\mathcal{Y}\mid\mathbf{T}=\mathbf{t})
\notag\\
&\quad+
\frac1n\sum_{\mathbf{t}}
\Pr(\mathbf{T}=\mathbf{t},\,K_n>c_1n/\log n)
I(\mathbf{X};\mathcal{Y}\mid\mathbf{T}=\mathbf{t}),
\label{eq:split-cut-patterns}
\end{align}
where $(\dagger)$ follows from the definition of conditional
mutual information, and $(\dagger\dagger)$ follows from the law of
total probability by separating the cut locations according to
whether $K_n\leq c_1n/\log n$ or $K_n>c_1n/\log n$.

For the cut patterns with $K_n\leq c_1n/\log n$, we bound
$I(\mathbf{X};\mathcal{Y}\mid\mathbf{T}=\mathbf{t})$
using~\eqref{eq:partition-small-fragment-number}.
For the remaining cut patterns, we use the trivial bound
$I(\mathbf{X};\mathcal{Y}\mid\mathbf{T}=\mathbf{t})\leq H(\mathbf{X})\leq n$.
Given $\mathbf{T}=\mathbf{t}$, the number of fragments $K_n$ and the lengths
$L_{n,j}$ are fixed, so averaging the first bound over $\mathbf{t}$ turns
its sum into an expectation.
Substituting these bounds into~\eqref{eq:split-cut-patterns} shows
\begin{align}
\frac1n I(\mathbf{X};\mathcal{Y})
&\leq
\frac1n\mathbb{E}\left[
\mathbf{1}_{\{K_n\leq c_1n/\log n\}}
\sum_{j=1}^{K_n}(\kappa L_{n,j}-\log n)^+
\right]
\notag\\
&\quad+\bigl((1-\lambda)c_1+e_n\bigr)\Pr(K_n\leq c_1n/\log n)
+\Pr(K_n>c_1n/\log n)
\notag\\
&\overset{(\dagger)}{\leq}
\frac1n\mathbb{E}\left[
\sum_{j=1}^{K_n}(\kappa L_{n,j}-\log n)^+
\right]
+(1-\lambda)c_1+e_n
+\Pr(K_n>c_1n/\log n),
\label{eq:partition-final-finite}
\end{align}
where $(\dagger)$ drops the indicator, which can only increase the
expectation since every summand is nonnegative, and uses
$\Pr(K_n\leq c_1n/\log n)\leq1$.



Now we prove the main statement~\eqref{eq:partition-converse}:
\begin{align}
\limsup_{n\to\infty}\frac1n
\sup_{P_{\mathbf{X}}}I(\mathbf{X};\mathcal{Y})
&\overset{\eqref{eq:partition-final-finite}}{\leq}
\lim_{\epsilon,\delta\to0}\limsup_{n\to\infty}
\left\{
\frac1n\mathbb{E}\left[
\sum_{j=1}^{K_n}(\kappa L_{n,j}-\log n)^+
\right]
+(1-\lambda)c_1+e_n
+\Pr(K_n>c_1n/\log n)
\right\}
\notag\\
&\overset{(\dagger)}{=}
\lim_{\epsilon,\delta\to0}
\left\{
\limsup_{n\to\infty}\frac1n
\mathbb{E}\left[
\sum_{j=1}^{K_n}(\kappa L_{n,j}-\log n)^+
\right]
+c_1\left(1-\frac{\kappa(1-\delta)}
{\kappa+\epsilon}\right)
\right\}
\notag\\
&\overset{(\dagger\dagger)}{=}
\limsup_{n\to\infty}\frac1n
\mathbb{E}\left[
\sum_{j=1}^{K_n}(\kappa L_{n,j}-\log n)^+
\right],
\notag
\end{align}
where $(\dagger)$ follows since $e_n\to0$ and
$\Pr(K_n>c_1n/\log n)\to0$ as $n\to\infty$
for each fixed $\epsilon,\delta$.
Equality $(\dagger\dagger)$ follows from
$\kappa(1-\delta)/(\kappa+\epsilon)\to1$
as $\epsilon,\delta\to0$. \qedhere

Choose a fixed $c_1>\alpha$. We have
\begin{align}
\frac1n\mathbb{E}\left[
\sum_{1\leq j\leq c_1n/\log n}N_{n,j}
\right]
&=\frac1n\sum_{1\leq j\leq c_1n/\log n}
\mathbb{E}[N_{n,j}]=\frac{\ell_n}{n}
\sum_{1\leq j\leq c_1n/\log n}1\notag\\
&\overset{}{=}
\frac{\ell_n}{\log n}c_1+O(\ell_n/n)
\overset{\eqref{eq:renewal-assumptions}}{\longrightarrow}
\frac{c_1}{\alpha}>1
\qquad(n\to\infty).
\label{eq:convergence of mean}
\end{align}


Then, for all sufficiently large $n$, we have
\begin{align}
\Pr(K_n>c_1n/\log n)
&\overset{(a)}{=}
\Pr\left(
\sum_{1\leq j\leq c_1n/\log n}N_{n,j}<n
\right)
\notag\\
&\overset{(b)}{\leq}
\frac{
\operatorname{Var}\left(\sum_{1\leq j\leq c_1n/\log n}N_{n,j}\right)}
{\left(
\mathbb{E}\left[\sum_{1\leq j\leq c_1n/\log n}N_{n,j}\right]-n
\right)^2}
\notag\\
&\overset{(c)}{\leq}
\frac{
4\operatorname{Var}\left(\sum_{1\leq j\leq c_1n/\log n}N_{n,j}\right)}
{(c_1/\alpha-1)^2n^2}
\notag\\
&\overset{(d)}{\leq}
\frac{4c_1\mathbb{E}[N_{n,1}^2]}
{(c_1/\alpha-1)^2n\log n}
\overset{\eqref{eq:renewal-assumptions}}{=}
O\left(\frac{\log n}{n}\right)
\longrightarrow0
\qquad(n\to\infty),
\notag
\end{align}
where $(a)$ follows since more than $c_1n/\log n$
fragments are needed exactly when the sampled
lengths in the sum do not reach $n$.
Inequality~$(b)$ follows from Chebyshev's
inequality. When the sum is less than $n$,
its distance from its mean is greater than
the mean minus $n$.
Inequality~$(c)$ follows from~\eqref{eq:convergence of mean}.
In particular,
\begin{align*}
\frac1n\mathbb{E}\left[
\sum_{1\leq j\leq c_1n/\log n}N_{n,j}
\right]
&\geq
\frac{c_1}{\alpha}
-\frac12\left(\frac{c_1}{\alpha}-1\right)
=1+\frac12\left(\frac{c_1}{\alpha}-1\right).
\end{align*}
Inequality~$(d)$ follows from the
independence and identical distribution of the
sampled lengths:
independence allows us to add
their variances:
\begin{align*}
\operatorname{Var}\left(
\sum_{1\leq j\leq c_1n/\log n}N_{n,j}
\right)
&=\sum_{1\leq j\leq c_1n/\log n}\operatorname{Var}(N_{n,j})\\
&=\sum_{1\leq j\leq c_1n/\log n}
\bigl(\mathbb{E}[N_{n,1}^2]-\ell_n^2\bigr)
\leq
\frac{c_1n}{\log n}\mathbb{E}[N_{n,1}^2].
\end{align*}


We have shown that $\Pr(K_n\leq c_1n/\log n)\to1$, so
Lemma~\ref{lem:partition} applies, and it remains to bound the expected
sum in~\eqref{eq:partition-converse}.
\begin{align}
\mathbb{E}\left[
\sum_{j=1}^{K_n}(\kappa N_{n,j}-\log n)^+
\right]
&\overset{(\dagger)}{=}\sum_{j=1}^{n}\Pr(K_n\geq j)
\mathbb{E}[(\kappa N_{n,1}-\log n)^+]
\notag\\
&\overset{\eqref{eq:reward-rate}}{=}
r_n(\kappa)\sum_{j=1}^{n}\Pr(K_n\geq j)\ell_n
\overset{(\dagger\dagger)}{=}
r_n(\kappa)\mathbb{E}\left[\sum_{j=1}^{K_n}N_{n,j}\right],
\label{eq:sampled-fragment-expectation}
\end{align}
where $(\dagger)$ and $(\dagger\dagger)$ follow from Wald's
equation~\cite{wald1944cumulative} (see also~\cite{wikiWald}), applied to the i.i.d.\ sequences
$((\kappa N_{n,j}-\log n)^+)_{j\geq1}$ and $(N_{n,j})_{j\geq1}$,
respectively.
It applies since $K_n\leq n$ and the event
$\{K_n\geq j\}=\{S_{n,j-1}<n\}$ is determined by
$N_{n,1},\ldots,N_{n,j-1}$, and is therefore independent of $N_{n,j}$.




Every actual fragment length satisfies
$L_{n,j}\leq N_{n,j}$,
which provides
\begin{align}
\frac1n\mathbb{E}\left[
\sum_{j=1}^{K_n}(\kappa L_{n,j}-\log n)^+
\right]
&\leq
\frac1n\mathbb{E}\left[
\sum_{j=1}^{K_n}(\kappa N_{n,j}-\log n)^+
\right]
\notag\\
&\overset{\eqref{eq:sampled-fragment-expectation}}{=}
\frac{r_n(\kappa)}{n}
\mathbb{E}\left[\sum_{j=1}^{K_n}N_{n,j}\right]
\notag\\
&\overset{(\dagger)}{\leq}
r_n(\kappa)\left(
1+\sqrt{\frac{\mathbb{E}[N_{n,1}^2]}{n}}
\right)
\overset{\eqref{eq:renewal-assumptions}}{=}
r_n(\kappa)+o(1)
\qquad(n\to\infty),
\label{eq:expected-fragment-upper}
\end{align}
where $(\dagger)$ follows since
$\sum_{j=1}^{K_n}N_{n,j}
\leq n+\max_{1\leq j\leq n}N_{n,j}$
and
$\mathbb{E}[\max_{1\leq j\leq n}N_{n,j}]
\leq\sqrt{\mathbb{E}[\sum_{j=1}^{n}N_{n,j}^2]}
=\sqrt{n\mathbb{E}[N_{n,1}^2]}$.


Applying
Lemma~\ref{lem:partition} therefore implies
\begin{align*}
\limsup_{n\to\infty}\frac1n
\sup_{P_{\mathbf{X}}}I(\mathbf{X};\mathcal{Y})
&\overset{\eqref{eq:partition-converse}}{\leq}
\limsup_{n\to\infty}\frac1n
\mathbb{E}\left[
\sum_{j=1}^{K_n}(\kappa L_{n,j}-\log n)^+
\right]
\overset{\eqref{eq:expected-fragment-upper}}{\leq}
\limsup_{n\to\infty}r_n(\kappa). \qedhere
\end{align*}

\label{lem:sampled-mixture-variance}
For every $\mathbf{y}\in\{0,1\}^k$, we have
\begin{align*}
 \mathbb{E}[\hat{P}^\circ(\mathbf{y})]
 =\widetilde{P}^\circ(\mathbf{y}) \mbox{ and }
 \operatorname{Var}(\hat{P}^\circ(\mathbf{y}))
 \leq\frac{2^{k(\kappa+\epsilon/2)}}{J_k}
 2^{-k}\widetilde{P}^\circ(\mathbf{y}).
\end{align*}

\label{lem:type}
For the distributions in Definition~\ref{def:fixed-fragment-output},
we have
\begin{equation*}
 D(\Lambda_{\mathbf{x}}\|\widetilde{P}_{\mathbf{x}}^{\otimes m})\le m\log e.
\end{equation*}

