We now prove the relative-entropy bound. 
It is enough to show that
\begin{align*}
\Lambda_{\mathbf{x}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)
&\leq e^m\widetilde{P}_{\mathbf{x}}^{\otimes m}
(\mathbf{y}_1,\ldots,\mathbf{y}_m)
\end{align*}
for every ordered tuple of noisy strings~$\mathbf{y}_1,\ldots,\mathbf{y}_m$.
To compare the two joint distributions, we first consider
the binary strings before adding noise. 
The fixed tuple
$\mathbf{x}$ contains $m_{\mathbf{a}}$ copies of each string
$\mathbf{a}\in\{0,1\}^k$.
Permuting its indices preserves
exactly these numbers of copies.
In the second joint distribution, the number of selections of a string may differ from its number of copies in \(\mathbf{x}\).
We condition on selecting exactly
$m_{\mathbf{a}}$ copies of every string $\mathbf{a}$ among the
$m$ selections. 
We will show that, under this condition,
the selected tuple has the same distribution as a
uniform reordering of $\mathbf{x}$. 
The probability of
satisfying this condition will then control the ratio
between the two noisy joint distributions.

Let $\mathcal{T}_{\mathbf{x}}$ be the set of ordered tuples containing
exactly $m_{\mathbf{a}}$ copies of each string
$\mathbf{a}\in\{0,1\}^k$. 
For any fixed tuple in $\mathcal{T}_{\mathbf{x}}$, the
$m_{\mathbf{a}}$ indices carrying $\mathbf{a}$ can
be assigned to its positions in $m_{\mathbf{a}}!$ ways.
Consequently, every tuple in $\mathcal{T}_{\mathbf{x}}$ is produced
by exactly
$\prod_{\mathbf{a}:m_{\mathbf{a}}>0}m_{\mathbf{a}}!$
index permutations, and
\begin{align*}
|\mathcal{T}_{\mathbf{x}}|
&=\frac{m!}{\prod_{\mathbf{a}:m_{\mathbf{a}}>0}m_{\mathbf{a}}!}.
\end{align*}
Since all index permutations are equally likely, it follows that
uniform reordering provides probability
$1/|\mathcal{T}_{\mathbf{x}}|$ to every tuple in $\mathcal{T}_{\mathbf{x}}$.

We next calculate the probability assigned to this set by independent selection.
For every
$\mathbf{u}=(\mathbf{u}_1,\ldots,\mathbf{u}_m)
\in\mathcal{T}_{\mathbf{x}}$,
\begin{align*}
P_{\mathbf{x}}^{\otimes m}(\mathbf{u})
&=\prod_{j=1}^m P_{\mathbf{x}}(\mathbf{u}_j)
=\prod_{\mathbf{a}:m_{\mathbf{a}}>0}
\left(\frac{m_{\mathbf{a}}}m\right)^{m_{\mathbf{a}}}
\end{align*}
and
\begin{align*}
P_{\mathbf{x}}^{\otimes m}(\mathcal{T}_{\mathbf{x}})
&=\frac{m!}{\prod_{\mathbf{a}:m_{\mathbf{a}}>0}m_{\mathbf{a}}!}
\prod_{\mathbf{a}:m_{\mathbf{a}}>0}
\left(\frac{m_{\mathbf{a}}}m\right)^{m_{\mathbf{a}}}.
\end{align*}
Thus, for every $\mathbf{u}\in\mathcal{T}_{\mathbf{x}}$,
\begin{align}
\frac{P_{\mathbf{x}}^{\otimes m}(\mathbf{u})}
{P_{\mathbf{x}}^{\otimes m}(\mathcal{T}_{\mathbf{x}})}
&=\frac1{|\mathcal{T}_{\mathbf{x}}|}.
\label{eq:type-conditional-uniform}
\end{align}

We now compare the probabilities of a fixed noisy tuple
$(\mathbf{y}_1,\ldots,\mathbf{y}_m)\in(\{0,1\}^k)^m$.
We first express $\Lambda_{\mathbf{x}}$ as an average over uniform
reorderings of $\mathbf{x}$ which provides
\begin{align*}
\Lambda_{\mathbf{x}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)
&\overset{}{=}
\frac1{|\mathcal{T}_{\mathbf{x}}|}
\sum_{\mathbf{u}\in\mathcal{T}_{\mathbf{x}}}
\prod_{j=1}^m W_k(\mathbf{y}_j\mid\mathbf{u}_j)
\\
&\overset{\eqref{eq:type-conditional-uniform}}{=}
\frac1{P_{\mathbf{x}}^{\otimes m}(\mathcal{T}_{\mathbf{x}})}
\sum_{\mathbf{u}\in\mathcal{T}_{\mathbf{x}}}
P_{\mathbf{x}}^{\otimes m}(\mathbf{u})
\prod_{j=1}^m W_k(\mathbf{y}_j\mid\mathbf{u}_j)
\\
&\overset{(\dagger)}{\leq}
\frac1{P_{\mathbf{x}}^{\otimes m}(\mathcal{T}_{\mathbf{x}})}
\sum_{\mathbf{u}\in(\{0,1\}^k)^m}
\prod_{j=1}^m
P_{\mathbf{x}}(\mathbf{u}_j)
W_k(\mathbf{y}_j\mid\mathbf{u}_j)
\\
&\overset{}{=}
\frac1{P_{\mathbf{x}}^{\otimes m}(\mathcal{T}_{\mathbf{x}})}
\prod_{j=1}^m
\left(
\sum_{\mathbf{a}\in\{0,1\}^k}
P_{\mathbf{x}}(\mathbf{a})W_k(\mathbf{y}_j\mid\mathbf{a})
\right)
\\
&\overset{(\dagger\dagger)}{=}
\frac{\widetilde{P}_{\mathbf{x}}^{\otimes m}
(\mathbf{y}_1,\ldots,\mathbf{y}_m)}
{P_{\mathbf{x}}^{\otimes m}(\mathcal{T}_{\mathbf{x}})}
\end{align*}
where $(\dagger)$ follows by extending the sum from $\mathcal{T}_{\mathbf{x}}$ to all ordered
tuples in $(\{0,1\}^k)^m$ and
$(\dagger\dagger)$ follows from Definition~\ref{def:fixed-fragment-output}:
the sum inside the $j$th factor equals
$\widetilde{P}_{\mathbf{x}}(\mathbf{y}_j)$.
Multiplying these $m$ factors provides the probability
of the noisy tuple under
$\widetilde{P}_{\mathbf{x}}^{\otimes m}$.

Thus, taking logarithms of the probability ratio and averaging under \(\Lambda_{\mathbf{x}}\) yields
\begin{align}
D(\Lambda_{\mathbf{x}}\|\widetilde{P}_{\mathbf{x}}^{\otimes m})
&\leq-\log P_{\mathbf{x}}^{\otimes m}(\mathcal{T}_{\mathbf{x}}).
\label{eq:type-probability}
\end{align}
It remains to prove
$P_{\mathbf{x}}^{\otimes m}(\mathcal{T}_{\mathbf{x}})\geq e^{-m}$.

Note that,
\begin{align*}
\ln(m!)
&=\sum_{j=1}^m\ln j
\geq\int_1^m\ln t\,dt
=m\ln m-m+1
\geq m\ln m-m.
\end{align*}
Thus, $m!\geq(m/e)^m$.
We have
\begin{align}
P_{\mathbf{x}}^{\otimes m}(\mathcal{T}_{\mathbf{x}})
&=\frac{m!}{\prod_{\mathbf{a}:m_{\mathbf{a}}>0}m_{\mathbf{a}}!}
\prod_{\mathbf{a}:m_{\mathbf{a}}>0}
\left(\frac{m_{\mathbf{a}}}m\right)^{m_{\mathbf{a}}}
\notag\\
&\overset{(\dagger)}{\geq}
\frac{(m/e)^m}
{\prod_{\mathbf{a}:m_{\mathbf{a}}>0}m_{\mathbf{a}}^{m_{\mathbf{a}}}}
\prod_{\mathbf{a}:m_{\mathbf{a}}>0}
\left(\frac{m_{\mathbf{a}}}m\right)^{m_{\mathbf{a}}}
\notag\\
&\overset{}{=}
\frac{(m/e)^m}
{\prod_{\mathbf{a}:m_{\mathbf{a}}>0}m_{\mathbf{a}}^{m_{\mathbf{a}}}}
\frac{\prod_{\mathbf{a}:m_{\mathbf{a}}>0}m_{\mathbf{a}}^{m_{\mathbf{a}}}}
{m^{\sum_{\mathbf{a}:m_{\mathbf{a}}>0}m_{\mathbf{a}}}}
\notag\\
&\overset{(\dagger\dagger)}{=}
\frac{(m/e)^m}{m^m}
=\frac{m^m e^{-m}}{m^m}
=e^{-m}.
\label{eq:type-lower}
\end{align}
Here, $(\dagger)$ uses $m!\geq(m/e)^m$ and
$m_{\mathbf{a}}!\leq m_{\mathbf{a}}^{m_{\mathbf{a}}}$ for every
$m_{\mathbf{a}}>0$ and
$(\dagger\dagger)$ follows from $\sum_{\mathbf{a}:m_{\mathbf{a}}>0}m_{\mathbf{a}}=m$.
Therefore,
\begin{align*}
D(\Lambda_{\mathbf{x}}\|\widetilde{P}_{\mathbf{x}}^{\otimes m})
&\overset{\eqref{eq:type-probability},\,\eqref{eq:type-lower}}{\leq}
-\log(e^{-m})=m\log e. \qedhere
\end{align*}

\label{prop:short}
For every $\epsilon>0$, there exists a finite constant $A$,
depending only on $p$ and $\epsilon$, such that for all
  integers $m\ge1$ and $k\ge 0$ ,
\begin{equation}
 \mathsf{C}_p(m,k)
 \leq k\left\lceil 2^{k(\kappa+\epsilon)}\right\rceil+Am,
 \label{eq:short-bound}
\end{equation}
where $\mathsf{C}_p$ is defined in Definition~\ref{definition:Csh}

If $k=0$, then $\mathsf{C}_p(m,0)=0$ and~\eqref{eq:short-bound} holds trivially, so assume $k\geq1$. Fix a tuple $\mathbf{x}=(\mathbf{x}_1,\ldots,\mathbf{x}_m)\in(\{0,1\}^k)^m$, and let $P_{\mathbf{x}}$ and $\Lambda_{\mathbf{x}}$ be as in Definition~\ref{def:fixed-fragment-output}.
By Lemma~\ref{lem:sparse}, choose $Q\in\mathcal{V}_k$
satisfying $D(\widetilde{P}_{\mathbf{x}}\|Q)\leq A_0$.
We first combine this approximation bound with
Lemma~\ref{lem:type} to bound
$D(\Lambda_{\mathbf{x}}\|Q^{\otimes m})$.

For every ordered tuple
$(\mathbf{y}_1,\ldots,\mathbf{y}_m)\in(\{0,1\}^k)^m$,
where each $\mathbf{y}_j$ is one length-$k$ string, we have
\begin{align}
\log\frac{\Lambda_{\mathbf{x}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)}
{Q^{\otimes m}(\mathbf{y}_1,\ldots,\mathbf{y}_m)}
&=
\log\frac{\Lambda_{\mathbf{x}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)}
{\widetilde{P}_{\mathbf{x}}^{\otimes m}(\mathbf{y}_1,\ldots,\mathbf{y}_m)}
+
\log\frac{\widetilde{P}_{\mathbf{x}}^{\otimes m}(\mathbf{y}_1,\ldots,\mathbf{y}_m)}
{Q^{\otimes m}(\mathbf{y}_1,\ldots,\mathbf{y}_m)}
\notag\\
&=
\log\frac{\Lambda_{\mathbf{x}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)}
{\widetilde{P}_{\mathbf{x}}^{\otimes m}(\mathbf{y}_1,\ldots,\mathbf{y}_m)}
+
\log\prod_{j=1}^m
\frac{\widetilde{P}_{\mathbf{x}}(\mathbf{y}_j)}{Q(\mathbf{y}_j)}
\notag\\
&=
\log\frac{\Lambda_{\mathbf{x}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)}
{\widetilde{P}_{\mathbf{x}}^{\otimes m}(\mathbf{y}_1,\ldots,\mathbf{y}_m)}
+
\sum_{j=1}^m
\log\frac{\widetilde{P}_{\mathbf{x}}(\mathbf{y}_j)}{Q(\mathbf{y}_j)}.
\label{eq:product-log-split}
\end{align}

We multiply both sides of~\eqref{eq:product-log-split}
by $\Lambda_{\mathbf{x}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)$ and sum over
all $\mathbf{y}_1,\ldots,\mathbf{y}_m\in\{0,1\}^k$.
We have
\begin{align}
\sum_{\mathbf{y}_1,\ldots,\mathbf{y}_m\in\{0,1\}^k}
\Lambda_{\mathbf{x}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)
\log\frac{\widetilde{P}_{\mathbf{x}}(\mathbf{y}_j)}{Q(\mathbf{y}_j)}
&\overset{}{=}
\sum_{\mathbf{z}\in\{0,1\}^k}
\left(
\sum_{\substack{
\mathbf{y}_1,\ldots,\mathbf{y}_m\in\{0,1\}^k\\
\mathbf{y}_j=\mathbf{z}}}
\Lambda_{\mathbf{x}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)
\right)
\log\frac{\widetilde{P}_{\mathbf{x}}(\mathbf{z})}{Q(\mathbf{z})}
\notag\\
&\overset{(\dagger)}{=}
\sum_{\mathbf{z}\in\{0,1\}^k}
\widetilde{P}_{\mathbf{x}}(\mathbf{z})
\log\frac{\widetilde{P}_{\mathbf{x}}(\mathbf{z})}{Q(\mathbf{z})}
=D(\widetilde{P}_{\mathbf{x}}\|Q),
\label{eq:single-output-divergence}
\end{align}
where $(\dagger)$ follows from the uniform permutation
and~\eqref{eq:empirical-noisy-law}.
Each  index $i\in[m]$ has probability $1/m$
of occupying position $j$. 
Conditional on this choice,
the noisy string at that position equals $\mathbf{z}$
with probability $W_k(\mathbf{z}\mid\mathbf{x}_i)$. Therefore,
\begin{align*}
\sum_{\substack{
\mathbf{y}_1,\ldots,\mathbf{y}_m\in\{0,1\}^k\\
\mathbf{y}_j=\mathbf{z}}}
\Lambda_{\mathbf{x}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)
&=\frac1m\sum_{i=1}^m W_k(\mathbf{z}\mid\mathbf{x}_i)
\overset{\eqref{eq:empirical-noisy-law}}{=}
\widetilde{P}_{\mathbf{x}}(\mathbf{z}).
\end{align*}
Finally, we have
\begin{align*}
D(\Lambda_{\mathbf{x}}\|Q^{\otimes m})
&\overset{\eqref{eq:product-log-split}}{=}
D(\Lambda_{\mathbf{x}}\|\widetilde{P}_{\mathbf{x}}^{\otimes m})
+
\sum_{j=1}^m
\sum_{\mathbf{y}_1,\ldots,\mathbf{y}_m\in\{0,1\}^k}
\Lambda_{\mathbf{x}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)
\log\frac{\widetilde{P}_{\mathbf{x}}(\mathbf{y}_j)}{Q(\mathbf{y}_j)}
\\
&\overset{\eqref{eq:single-output-divergence}}{=}
D(\Lambda_{\mathbf{x}}\|\widetilde{P}_{\mathbf{x}}^{\otimes m})
+mD(\widetilde{P}_{\mathbf{x}}\|Q)
\end{align*}
which proves~\eqref{eq:product-marginal-identity}.
Consequently,
\begin{align}
D(\Lambda_{\mathbf{x}}\|Q^{\otimes m})
&\overset{\eqref{eq:product-marginal-identity}}{=}
D(\Lambda_{\mathbf{x}}\|\widetilde{P}_{\mathbf{x}}^{\otimes m})
+mD(\widetilde{P}_{\mathbf{x}}\|Q)
\overset{\text{Lemma}~\ref{lem:sparse},~\ref{lem:type}}\leq m\log e+mA_0
=m(\log e+A_0).
\label{eq:product-divergence}
\end{align}

We now compare $\Lambda_{\mathbf{x}}$ with the fixed distribution
$R$ defined in~\eqref{eq:reference-mixture}.
The selected $Q$ may depend on $\mathbf{x}$, but it always
belongs to $\mathcal{V}_k$.
Hence, $Q^{\otimes m}$ appears
in the average defining $R$ with weight $1/|\mathcal{V}_k|$.
Since all other terms are nonnegative, for every
$\mathbf{y}_1,\ldots,\mathbf{y}_m\in\{0,1\}^k$,
\begin{align}
R(\mathbf{y}_1,\ldots,\mathbf{y}_m)
&\overset{\eqref{eq:reference-mixture}}{\geq}
\frac1{|\mathcal{V}_k|}
Q^{\otimes m}(\mathbf{y}_1,\ldots,\mathbf{y}_m).
\label{eq:reference-component}
\end{align}
Consequently,
\begin{align}
D(\Lambda_{\mathbf{x}}\|R)
&=
\sum_{\mathbf{y}_1,\ldots,\mathbf{y}_m\in\{0,1\}^k}
\Lambda_{\mathbf{x}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)
\log\frac{\Lambda_{\mathbf{x}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)}
{R(\mathbf{y}_1,\ldots,\mathbf{y}_m)}
\notag\\
&\overset{\eqref{eq:reference-component}}{\leq}
\sum_{\mathbf{y}_1,\ldots,\mathbf{y}_m\in\{0,1\}^k}
\Lambda_{\mathbf{x}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)
\log\frac{|\mathcal{V}_k|\Lambda_{\mathbf{x}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)}
{Q^{\otimes m}(\mathbf{y}_1,\ldots,\mathbf{y}_m)}
\notag\\
&=\log|\mathcal{V}_k|+D(\Lambda_{\mathbf{x}}\|Q^{\otimes m})
\notag\\
&\overset{\eqref{eq:product-divergence}}{\leq}
\log|\mathcal{V}_k|+m(\log e+A_0)
\notag\\
&\overset{(\dagger)}{\leq}
k\left\lceil2^{k(\kappa+\epsilon)}\right\rceil
+m(\log e+A_0)
\label{eq:reference-divergence}
\end{align}
where $(\dagger)$ follows from
Construction~\ref{con:sparse-family}, which provides
$|\mathcal{V}_k|\leq2^{kJ_k}$ and
$J_k=\lceil2^{k(\kappa+\epsilon)}\rceil$.


It remains to turn everything into a
mutual-information bound. Allow the random tuple $\mathbf{X}$  to have
any joint distribution $P_{\mathbf{X}}$.
For its randomly ordered noisy tuple
$\mathbf{Y}=(\mathbf{Y}_1,\ldots,\mathbf{Y}_m)$,  the distribution
satisfies
\begin{align}
P_{\mathbf{Y}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)
&=\sum_{\mathbf{x}}
P_{\mathbf{X}}(\mathbf{x})
\Lambda_{\mathbf{x}}(\mathbf{y}_1,\ldots,\mathbf{y}_m).
\label{eq:noisy-tuple-law}
\end{align}


Then, we have:
\begin{align}
\mathbb{E}_{\mathbf{X}}\!\left[D(\Lambda_{\mathbf{X}}\|R)\right]
&=\sum_{\mathbf{x}}P_{\mathbf{X}}(\mathbf{x})D(\Lambda_{\mathbf{x}}\|R)\notag\\
&=
\sum_{\mathbf{x}}
\sum_{\mathbf{y}_1,\ldots,\mathbf{y}_m\in\{0,1\}^k}
P_{\mathbf{X}}(\mathbf{x})
\Lambda_{\mathbf{x}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)
\log\frac{\Lambda_{\mathbf{x}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)}
{R(\mathbf{y}_1,\ldots,\mathbf{y}_m)}
\notag\\
&\overset{}{=}
\sum_{\mathbf{x}}
\sum_{\mathbf{y}_1,\ldots,\mathbf{y}_m\in\{0,1\}^k}
P_{\mathbf{X}}(\mathbf{x})
\Lambda_{\mathbf{x}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)
\left[
\log\frac{\Lambda_{\mathbf{x}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)}
{P_{\mathbf{Y}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)}
+
\log\frac{P_{\mathbf{Y}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)}
{R(\mathbf{y}_1,\ldots,\mathbf{y}_m)}
\right]
\notag\\
&=
\sum_{\mathbf{x}}
\sum_{\mathbf{y}_1,\ldots,\mathbf{y}_m\in\{0,1\}^k}
P_{\mathbf{X}}(\mathbf{x})
\Lambda_{\mathbf{x}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)
\log\frac{\Lambda_{\mathbf{x}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)}
{P_{\mathbf{Y}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)}
\notag\\
&\quad+
\sum_{\mathbf{y}_1,\ldots,\mathbf{y}_m\in\{0,1\}^k}
\left(
\sum_{\mathbf{x}}
P_{\mathbf{X}}(\mathbf{x})
\Lambda_{\mathbf{x}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)
\right)
\log\frac{P_{\mathbf{Y}}(\mathbf{y}_1,\ldots,\mathbf{y}_m)}
{R(\mathbf{y}_1,\ldots,\mathbf{y}_m)}
\notag\\
&\overset{\eqref{eq:noisy-tuple-law}}{=}
I(\mathbf{X};\mathbf{Y})+D(P_{\mathbf{Y}}\|R)
\geq I(\mathbf{X};\mathbf{Y}).
\label{eq:information-radius}
\end{align}


Finally, the unordered multiset $\mathcal{Y}$ is obtained
from $\mathbf{Y}$ by forgetting its order. Thus,
observing $\mathbf{Y}$ provides at least as much
information about $\mathbf{X}$ as observing $\mathcal{Y}$, and
\begin{align*}
I(\mathbf{X};\mathcal{Y})
&\leq I(\mathbf{X};\mathbf{Y})
\overset{\eqref{eq:information-radius}}{\leq}
\mathbb{E}_{\mathbf{X}}\!\left[D(\Lambda_{\mathbf{X}}\|R)\right]
\overset{\eqref{eq:reference-divergence}}{\leq}
k\left\lceil2^{k(\kappa+\epsilon)}\right\rceil
+m(\log e+A_0).
\end{align*}
This holds for every joint distribution
$P_{\mathbf{X}}$. Taking the supremum proves
\eqref{eq:short-bound} with $A=\log e+A_0$,
which depends only on $p$ and $\epsilon$.

\label{lem:sorted-suffix-noise}

Under Construction~\ref{con:suffix-sorting},
\begin{align}
H(\mathbf{D}\mid\mathbf{A},\mathbf{B})=H(\mathbf{D}\mid\mathbf{X},\mathbf{A},\mathbf{B})=m(L-k)h_2(p).
\label{eq:suffix-noise-entropy}
\end{align}

\label{lem:prefix-suffix-information}
Under Construction~\ref{con:suffix-sorting},
\begin{align}
I(\mathbf{X};\mathbf{A})&\leq\mathsf{C}_p(m,k),
\label{eq:sorted-prefix-information}\\
I(\mathbf{X};\mathbf{D}\mid\mathbf{A})&\leq m\kappa(L-k).
\label{eq:sorted-suffix-information}
\end{align}

\label{lem:suffix}
For every integer $m\geq1$ and integers $0\leq k\leq L$,
\begin{align}
\mathsf{C}_p(m,L)&\leq\mathsf{C}_p(m,k)+m\kappa(L-k).
\label{eq:suffix-bound}
\end{align}

\label{lem:partition-counts}
Fix integers $n\geq2$ and $1\leq K\leq n$, and partition
$n$ into $K$ positive integer lengths. Let $m_L$ be the
number of fragments of length $L$ and
$\mathcal{L}=\{L\in[n]:m_L>0\}$.
Thus, we have $\sum_{L\in\mathcal{L}}m_L=K$ and
$\sum_{L\in\mathcal{L}}Lm_L=n$.
\begin{enumerate}
    \renewcommand{(\Alph{enumi})}{(\Alph{enumi})}
    \renewcommand{(\Alph{enumi})}{(\Alph{enumi})}
\item\label{lemma:A}  We have $|\mathcal{L}|(|\mathcal{L}|+1)/2\leq n$, and hence $|\mathcal{L}|\leq\sqrt{2n}$.
\item\label{lemma:B} 
\begin{align}
\sum_{L\in\mathcal{L}}m_L\log\frac{n}{m_L}
&\leq 2K\log\frac{n}{K}+K\log e.
\label{eq:counts-entropy}
\end{align}
\item\label{lemma:C} For every fixed $\delta\in(0,1)$,
\begin{align}
\sum_{L\in\mathcal{L}}m_L^{1-\delta}\log(m_L+1)
&\leq\log(n+1)(2n)^{\delta/2}K^{1-\delta}.
\label{eq:counts-power}
\end{align}
\end{enumerate}

Fix $\delta\in(0,1)$. Since $m_L\leq n$ for every
$L\in\mathcal{L}$, we have
\begin{align*}
\sum_{L\in\mathcal{L}}m_L^{1-\delta}\log(m_L+1)
&\leq\log(n+1)\sum_{L\in\mathcal{L}}m_L^{1-\delta}
\overset{(\dagger)}{\leq}
\log(n+1)|\mathcal{L}|^\delta K^{1-\delta}\overset{\text{Lemma}~\ref{lem:partition-counts}. \ref{lemma:A}}{\leq}
\log(n+1)(2n)^{\delta/2}K^{1-\delta}.
\end{align*}
Here $(\dagger)$ follows from the concavity of
$x^{1-\delta}$ and $\sum_{L\in\mathcal{L}}m_L=K$, which provide
\begin{align*}
\frac1{|\mathcal{L}|}\sum_{L\in\mathcal{L}}m_L^{1-\delta}
&\leq
\left(\frac1{|\mathcal{L}|}\sum_{L\in\mathcal{L}}m_L\right)^{1-\delta}
=\left(\frac{K}{|\mathcal{L}|}\right)^{1-\delta}. \qedhere
\end{align*}

\label{lem:entropy-continuity}
If $P$ and $Q$ are distributions on the same alphabet of size $M$
and $d=\frac12\|P-Q\|_1$, then
\begin{equation}
 |H(P)-H(Q)|\le h_2(d)+d\log M.
 \label{eq:entropy-continuity}
\end{equation}
